<?php
declare(strict_types=1); require_once __DIR__.'/../includes/ui.php'; $active=$application->activeCompanyContext()->currentForUser($currentUser->id()); if(!$active){$session->flash('warning','Nenhuma empresa está selecionada.');header('Location: '.$application->redirect()->applicationUrl('admin-empresas.php'),true,303);exit;} $company=$application->companyAdmin()->find($active->companyId()); if(!$company){$session->flash('danger','Não foi possível consultar a empresa selecionada.');header('Location: '.$application->redirect()->applicationUrl('admin-empresas.php'),true,303);exit;} $users=$application->companyAdmin()->users($active->companyId()); ?>
<div class="page-body admin-company-panel"><section class="panel"><div class="panel-header"><div class="panel-title"><i class="bi bi-building"></i> <?=h($active->name())?></div><span><?=ui_badge(ucfirst((string)$company['status']))?></span></div><div class="form-row-3"><div><strong>Documento</strong><br><?=h($company['documento']??'—')?></div><div><strong>Integração SO</strong><br><?=!empty($company['so_fornecedor_id'])?'Vinculada ao fornecedor '.$company['so_fornecedor_id']:'Sem vínculo'?></div><div><strong>Cadastro</strong><br><?=h($company['criado_em']??'—')?></div></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Usuários vinculados</div></div><?php if($users===[]):empty_state('Sem usuários vinculados','Esta empresa ainda não tem usuários associados.');else:?><div class="table-panel-wrap"><table class="os-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Status</th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><?=h($user['nome'])?></td><td><?=h($user['email'])?></td><td><?=h($user['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div>
